  1137	def _compact_wy(qr: torch.Tensor, tau: torch.Tensor):
  1138	    """Convert geqrf's packed panel to Q = I - V T V.T."""
  1139	    batch, rows, width = qr.shape
  1140	    v = torch.tril(qr, diagonal=-1)
  1141	    v = v + torch.eye(rows, width, dtype=qr.dtype, device=qr.device)
  1142	    t = torch.zeros((batch, width, width), dtype=qr.dtype, device=qr.device)
  1143	    for column in range(width):
  1144	        t[:, column, column] = tau[:, column]
  1145	        if column:
  1146	            overlap = torch.bmm(
  1147	                v[:, :, :column].transpose(1, 2),
  1148	                v[:, :, column : column + 1],
  1149	            )
  1150	            coefficient = -tau[:, column, None, None] * overlap
  1151	            t[:, :column, column : column + 1] = torch.bmm(
  1152	                t[:, :column, :column], coefficient
  1153	            )
  1154	    return v, t
